# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Tuple
from rosterkit.models import Student
from rosterkit.errors import ProjectError


# ---
def check_emails(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students to list")
    for student in students:
        if not student.email:
            name = student.display_name
            raise ProjectError(f"no email for {name}")


# ---
def contact_cells(student: Student) -> Tuple[str, ...]:
    return (
        student.display_name, student.section, student.email
    )


# ---
def join_cells(
    cells: Tuple[str, ...], sizes: List[int]
) -> str:
    padded = [
        part.ljust(size) for part, size in zip(cells, sizes)
    ]
    return "  ".join(padded).rstrip()


# ---
def contact_rows(students: List[Student]) -> List[str]:
    """Sorted, aligned name, section and email rows."""
    check_emails(students)
    cells = sorted(contact_cells(item) for item in students)
    widths = [max(map(len, part)) for part in zip(*cells)]
    return [join_cells(cell, widths) for cell in cells]
